"""Test-only deterministic replay harness, built strictly on the public API.

Nothing in this module is a product surface: it only exercises
``ActorRuntime.register/send/run/get_state/pending_count/trace`` and the
documented exceptions (``ValueError``/``TypeError``/``LookupError``/
``ActorExecutionError``).  Facilities the baseline deliberately does not ship
(timed delivery, durable recovery, supervision, deduplication, throughput
limits) are emulated *around* the public runtime, inside the test package:

* a virtual clock replaces wall-clock time; timer expiry is an explicit
  ``clock`` action, never ``time.sleep``;
* an append-only, length-framed JSON event journal stands in for a persistence
  log, and snapshot blobs stand in for checkpoints;
* supervision (resume / restart / stop / escalate) is expressed by replaying
  the durable record prefix against a fresh public runtime, which is exactly
  what journal-based recovery is;
* at-least-once duplicate delivery is a recorded delivery carrying the same
  dedup id;
* an in-flight cap emulates bounded scheduling by stepping the public
  ``run(limit=1)`` a fixed number of times per scheduling round.

First execution, journal replay and snapshot recovery all drive the *same*
interpreter over the *same* record stream, so equivalence is structural rather
than asserted by coincidence.

Durable bytes use ``json`` (ensure_ascii, allow_nan=False, sort_keys, compact
separators) with a 4-byte length frame per record, so equivalent journals are
byte-for-byte identical.  Corrupt frames raise :class:`CorruptRecordError`; a
snapshot/journal-header with an incompatible schema or codec raises
:class:`IncompatibleSnapshotError`.  Both are fixture-local error types: they
describe test persistence fixtures and are deliberately not product APIs.
"""
from __future__ import annotations

import io
import json
import struct
from dataclasses import dataclass, field
from typing import Any, Callable, Optional

from actor_runtime import ActorContext, ActorExecutionError, ActorRuntime

# ---------------------------------------------------------------------------
# Fixture-local error protocol (test persistence layer only)
# ---------------------------------------------------------------------------


class HarnessError(Exception):
    """Base class for errors raised by the test persistence fixtures."""


class CorruptRecordError(HarnessError):
    """A persisted journal frame cannot be decoded or authenticated."""


class IncompatibleSnapshotError(HarnessError):
    """A snapshot or journal header has an incompatible schema or codec."""


# ---------------------------------------------------------------------------
# Deterministic pseudo-random generator (fixed, never OS-seeded)
# ---------------------------------------------------------------------------


class DeterministicRng:
    """xorshift64*: a tiny fixed PRNG with stable cross-run behaviour.

    ``random.Random`` is avoided on purpose: its seeding/compact-state
    semantics are a CPython implementation detail replay equivalence should
    not depend on.
    """

    MULT = 0x2545F4914F6CDD1D
    MASK = (1 << 64) - 1

    def __init__(self, seed: int):
        state = int(seed) & self.MASK
        if state == 0:
            state = 0x9E3779B97F4A7C15  # xorshift never allows a zero state
        self._state = state

    def next_u64(self) -> int:
        x = self._state
        x ^= (x >> 12) & self.MASK
        x ^= (x << 25) & self.MASK
        x ^= (x >> 27) & self.MASK
        x &= self.MASK
        self._state = x
        return (x * self.MULT) & self.MASK

    def below(self, n: int) -> int:
        if n <= 0:
            raise ValueError("n must be positive")
        return self.next_u64() % n

    def choose(self, seq):
        return seq[self.below(len(seq))]

    def chance(self, p: int) -> bool:
        """Return True with probability p/100 (integer percentage)."""
        return self.below(100) < p


# ---------------------------------------------------------------------------
# Actor names and behaviour (all handler state is JSON-canonicalisable)
# ---------------------------------------------------------------------------

A_EVENTS = "events"
A_COUNTER = "counter"
A_SUPERVISOR = "supervisor"
A_CHILD = "child"
ACTOR_NAMES = (A_EVENTS, A_COUNTER, A_SUPERVISOR, A_CHILD)

# Message envelopes (plain JSON-able dicts):
#   events:     {"kind": "record", "event": E, "dedup"?: id, "then"?: inner}
#   counter:    {"kind": "inc", "n": int, "dedup"?: id}
#   supervisor: {"kind": "record", "event": E} / {"kind": "escalated","key"}
#   child:      {"kind": "record", "event": E, "dedup"?: id}
#   timer:      {"kind": "timer", "token": str, "dedup": id}
# injected faults: {"kind": "fail", "key": str}


def _dedup_then(state, message, mut, after):
    """Apply ``mut`` once per dedup id; ``after`` runs only on first apply.

    Every delivery still reaches the handler and is recorded as an arrival;
    a duplicate contributes no state change and no derived delivery.  State
    is replaced (never mutated in place), matching the runtime's atomic
    commit contract.
    """
    dedup_id = message.get("dedup")
    duplicate = dedup_id is not None and dedup_id in state["seen"]
    if duplicate:
        return {
            "seen": state["seen"],
            "arrivals": state["arrivals"] + [
                {"kind": message["kind"], "duplicate": True}
            ],
            "value": state["value"],
        }
    new_state = {
        "seen": set(state["seen"]),
        "arrivals": list(state["arrivals"]),
        "value": list(state["value"]) if isinstance(state["value"], list)
        else state["value"],
    }
    mut(new_state)
    new_state["arrivals"].append(
        {"kind": message["kind"], "duplicate": False}
    )
    if dedup_id is not None:
        new_state["seen"].add(dedup_id)
    if after is not None:
        after(new_state)
    return new_state


def events_handler(state, message, ctx: ActorContext):
    kind = message["kind"]
    if kind == "record":
        def mut(ns):
            ns["value"].append(message["event"])

        def after(ns):
            derived = message.get("then")
            if derived is not None:
                # Derived delivery: enqueued by the runtime only after this
                # handler returns successfully (async delivery interleaving).
                ctx.send(derived["to"], derived["msg"])

        return _dedup_then(state, message, mut, after)
    if kind == "timer":
        return _dedup_then(
            state, message,
            lambda ns: ns["value"].append({"timer": message["token"]}),
            None,
        )
    if kind == "fail":
        raise RuntimeError(f"events fault: {message['key']}")
    raise AssertionError(f"events actor got unexpected message: {message!r}")


def counter_handler(state, message, ctx: ActorContext):
    kind = message["kind"]
    if kind == "inc":
        return _dedup_then(
            state, message, lambda ns: ns.__setitem__(
                "value", ns["value"] + message["n"]
            ),
            None,
        )
    if kind == "fail":
        raise ValueError(f"counter fault: {message['key']}")
    raise AssertionError(f"counter actor got unexpected message: {message!r}")


def supervisor_handler(state, message, ctx: ActorContext):
    kind = message["kind"]
    if kind == "record":
        return {
            "observed": list(state["observed"]) + [message["event"]],
            "escalations": list(state["escalations"]),
        }
    if kind == "escalated":
        return {
            "observed": list(state["observed"]),
            "escalations": list(state["escalations"]) + [message["key"]],
        }
    if kind == "fail":
        raise RuntimeError(f"supervisor fault: {message['key']}")
    raise AssertionError(f"supervisor got unexpected message: {message!r}")


def child_handler(state, message, ctx: ActorContext):
    kind = message["kind"]
    if kind == "record":
        return _dedup_then(
            state, message,
            lambda ns: ns["value"].append(message["event"]),
            None,
        )
    if kind == "timer":
        return _dedup_then(
            state, message,
            lambda ns: ns["value"].append({"timer": message["token"]}),
            None,
        )
    if kind == "fail":
        raise RuntimeError(f"child fault: {message['key']}")
    raise AssertionError(f"child actor got unexpected message: {message!r}")


HANDLERS = {
    A_EVENTS: events_handler,
    A_COUNTER: counter_handler,
    A_SUPERVISOR: supervisor_handler,
    A_CHILD: child_handler,
}


def initial_state_for(name: str) -> Any:
    if name == A_SUPERVISOR:
        return {"observed": [], "escalations": []}
    value = 0 if name == A_COUNTER else []
    return {"seen": set(), "arrivals": [], "value": value}


def register_all(rt: ActorRuntime) -> None:
    for name in ACTOR_NAMES:
        rt.register(name, initial_state_for(name), HANDLERS[name])


def canonical_state(raw: Any) -> Any:
    """Normalise handler state for comparison: sets become sorted lists."""
    if isinstance(raw, dict) and "seen" in raw and "arrivals" in raw:
        return {
            "seen": sorted(raw["seen"]),
            "arrivals": raw["arrivals"],
            "value": raw["value"],
        }
    return raw


# ---------------------------------------------------------------------------
# Durable record codec
# ---------------------------------------------------------------------------

SCHEMA_VERSION = 1
CODEC = "json-v1"


def _json_dumps(obj: Any) -> bytes:
    return (
        json.dumps(
            obj, ensure_ascii=True, allow_nan=False,
            sort_keys=True, separators=(",", ":"),
        ) + "\n"
    ).encode("utf-8")


def _frame(rec: dict) -> bytes:
    body = _json_dumps(rec)
    return struct.pack("<I", len(body)) + body


def encode_records(records: list[dict]) -> bytes:
    out = bytearray()
    out += _frame({"t": "header", "schema": SCHEMA_VERSION, "codec": CODEC})
    for rec in records:
        out += _frame(rec)
    return bytes(out)


def _read_frame(stream: io.BytesIO) -> Optional[dict]:
    header = stream.read(4)
    if not header:
        return None
    if len(header) != 4:
        raise CorruptRecordError("truncated record header")
    (length,) = struct.unpack("<I", header)
    body = stream.read(length)
    if len(body) != length:
        raise CorruptRecordError("truncated record body")
    try:
        rec = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise CorruptRecordError(f"undecodable record: {exc}") from exc
    if not isinstance(rec, dict) or "t" not in rec:
        raise CorruptRecordError("record missing type tag")
    return rec


def parse_records(blob: bytes, *, start_offset: int = 0) -> list[dict]:
    stream = io.BytesIO(blob)
    stream.seek(start_offset)
    records = []
    first = _read_frame(stream)
    if first is None:
        raise CorruptRecordError("empty journal")
    if first.get("t") != "header":
        raise CorruptRecordError("journal missing header")
    if first.get("schema") != SCHEMA_VERSION:
        raise IncompatibleSnapshotError(
            f"journal schema {first.get('schema')!r} incompatible "
            f"with {SCHEMA_VERSION}"
        )
    if first.get("codec") != CODEC:
        raise IncompatibleSnapshotError(
            f"journal codec {first.get('codec')!r} unsupported"
        )
    while True:
        rec = _read_frame(stream)
        if rec is None:
            break
        records.append(rec)
    return records


def frame_offsets(blob: bytes) -> list[int]:
    """Byte offset of every frame (including the header) in ``blob``."""
    stream = io.BytesIO(blob)
    offsets = []
    while True:
        pos = stream.tell()
        header = stream.read(4)
        if not header:
            break
        if len(header) != 4:
            raise CorruptRecordError("truncated record header")
        (length,) = struct.unpack("<I", header)
        offsets.append(pos)
        if len(stream.read(length)) != length:
            raise CorruptRecordError("truncated record body")
    return offsets


def corrupt(blob: bytes) -> bytes:
    """Return a deterministically damaged copy of a journal blob."""
    if len(blob) < 12:
        return blob + b"\x00"
    damaged = bytearray(blob)
    damaged[len(damaged) // 2] ^= 0xFF
    return bytes(damaged)


def truncate(blob: bytes) -> bytes:
    """Return a copy cut mid-frame."""
    return blob[: max(5, len(blob) - 3)]


# ---------------------------------------------------------------------------
# Script normalisation: commands -> durable records
# ---------------------------------------------------------------------------
#
# Command tuple alphabet:
#   ("send", target, message, priority, want_dedup[=False], redeliver[=None])
#   ("schedule", target, token, delay, ttl, priority, want_dedup)
#   ("clock", ticks)
#   ("cap", n_or_none)
#   ("resolve",)
#   ("snapshot",)
#
# ``redeliver`` is the dedup id of an earlier dedup delivery; the resulting
# record is a fresh journaled delivery carrying that same id.


def normalize_script(script: list) -> list[dict]:
    records: list[dict] = []
    deliveries: dict[str, dict] = {}
    d_seq = 0
    t_seq = 0
    snap_seq = 0

    def new_dedup() -> str:
        nonlocal d_seq
        d_seq += 1
        return f"d{d_seq:04d}"

    for cmd in script:
        op = cmd[0]
        if op == "send":
            _, target, message, priority = cmd[0], cmd[1], cmd[2], cmd[3]
            want_dedup = cmd[4] if len(cmd) > 4 else False
            redeliver = cmd[5] if len(cmd) > 5 else None
            message = dict(message)
            message.pop("want_dedup", None)
            if redeliver is not None:
                original = deliveries[redeliver]
                dedup_id = original["dedup"]
                message = dict(original["message"])
                target = original["target"]
                priority = original["priority"]
                redelivery = True
            else:
                dedup_id = new_dedup() if want_dedup else None
                redelivery = False
                if dedup_id is not None:
                    message["dedup"] = dedup_id
                else:
                    message.pop("dedup", None)
            rec = {
                "t": "deliver",
                "target": target,
                "message": message,
                "priority": int(priority),
                "dedup": dedup_id,
                "redelivery": redelivery,
            }
            records.append(rec)
            if dedup_id is not None and not redelivery:
                deliveries[dedup_id] = rec
        elif op == "schedule":
            _, target, token, delay, ttl, priority, want_dedup = cmd
            t_seq += 1
            timer_id = f"t{t_seq:04d}"
            # The fired message reuses the schedule's dedup identity, so a
            # timer delivery participates in the same dedup contract.
            dedup_id = timer_id if want_dedup else None
            records.append({
                "t": "schedule",
                "id": timer_id,
                "target": target,
                "token": token,
                "delay": int(delay),
                "ttl": int(ttl),
                "priority": int(priority),
                "dedup": dedup_id,
            })
        elif op == "clock":
            records.append({"t": "clock", "ticks": int(cmd[1])})
        elif op == "cap":
            n = cmd[1]
            records.append({"t": "cap", "n": None if n is None else int(n)})
        elif op == "resolve":
            records.append({"t": "resolve"})
        elif op == "snapshot":
            snap_seq += 1
            records.append({"t": "snapshot", "seq": snap_seq})
        else:
            raise AssertionError(f"unknown command: {op!r}")
    return records


@dataclass
class PendingTimer:
    fire_at: int
    expire_at: int
    target: str
    message: dict
    priority: int
    timer_id: str


# ---------------------------------------------------------------------------
# Result
# ---------------------------------------------------------------------------


@dataclass
class ScenarioResult:
    states: dict
    traces: list                      # raw trace tuples of the live runtime
    gen_boundaries: list              # indices where a new generation starts
    events: list                      # JSON-able interpreter event ledger
    supervision: list
    delivered_dedup: list
    journal: bytes = b""
    snapshots: list = field(default_factory=list)  # [(seq, offset, blob)]

    def signature(self) -> bytes:
        """Byte signature of every contract-visible observation except the
        runtime-assigned message ids (compared separately)."""
        return _json_dumps({
            "states": self.states,
            "events": self.events,
            "supervision": self.supervision,
            "delivered_dedup": self.delivered_dedup,
        })

    def trace_quads(self) -> list:
        """Completion-order trace without runtime-assigned ids."""
        return [
            (e[1], e[2], e[3], e[4])  # actor, priority, before, after
            for e in self.traces
        ]


# ---------------------------------------------------------------------------
# Interpreter: first run, replay and recovery all share this code
# ---------------------------------------------------------------------------


DEFAULT_POLICY_OUTCOMES = {
    A_CHILD: ("restart", "escalate"),  # 1st fault restart, further escalate
    A_COUNTER: ("resume", "resume"),
    A_EVENTS: ("stop", "stop"),
    A_SUPERVISOR: ("escalate", "escalate"),
}


def default_policy(actor_name: str, attempts: int) -> str:
    outcomes = DEFAULT_POLICY_OUTCOMES[actor_name]
    return outcomes[min(attempts - 1, len(outcomes) - 1)]


class Interpreter:
    def __init__(self, *, cap: Optional[int] = None,
                 policy: Callable[[str, int], str] = default_policy):
        self.cap = cap
        self.policy = policy
        self.rt = ActorRuntime()
        register_all(self.rt)
        self.clock = 0
        self.stopped: set[str] = set()
        self.attempts: dict[str, int] = {}
        self.timers: list[PendingTimer] = []
        self.events: list[dict] = []
        self.supervision: list[dict] = []
        self.delivered_dedup: list[dict] = []
        self.gen_boundaries: list[int] = []
        self.pending_fault: Optional[dict] = None
        self.snapshots: list[tuple] = []
        self._snap_seq = 0

    # -- snapshots --------------------------------------------------------

    def snapshot_blob(self) -> bytes:
        states = {}
        for name in ACTOR_NAMES:
            if name in self.stopped:
                states[name] = {"stopped": True}
                continue
            raw = self.rt.get_state(name)
            states[name] = canonical_state(raw)
        payload = {
            "snapshot": {
                "schema": SCHEMA_VERSION,
                "codec": CODEC,
                "cap": self.cap,
                "clock": self.clock,
                "stopped": sorted(self.stopped),
                "attempts": dict(self.attempts),
                "states": states,
                "timers": [
                    {
                        "fire_at": t.fire_at,
                        "expire_at": t.expire_at,
                        "target": t.target,
                        "message": t.message,
                        "priority": t.priority,
                        "id": t.timer_id,
                    }
                    for t in self.timers
                ],
                "trace": [list(e) for e in self.rt.trace()],
                "gen_boundaries": list(self.gen_boundaries),
                "events": list(self.events),
                "supervision": list(self.supervision),
                "delivered_dedup": list(self.delivered_dedup),
            }
        }
        return _json_dumps(payload)

    def load_snapshot(self, blob: bytes) -> int:
        try:
            outer = json.loads(blob.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise CorruptRecordError(f"undecodable snapshot: {exc}") from exc
        snap = outer.get("snapshot") if isinstance(outer, dict) else None
        if not isinstance(snap, dict):
            raise CorruptRecordError("snapshot missing payload")
        if snap.get("schema") != SCHEMA_VERSION:
            raise IncompatibleSnapshotError(
                f"snapshot schema {snap.get('schema')!r} incompatible "
                f"with {SCHEMA_VERSION}"
            )
        if snap.get("codec") != CODEC:
            raise IncompatibleSnapshotError(
                f"snapshot codec {snap.get('codec')!r} unsupported"
            )
        self.cap = snap["cap"]
        self.clock = int(snap["clock"])
        self.stopped = set(snap.get("stopped", []))
        self.attempts = dict(snap.get("attempts", {}))
        self.timers = [
            PendingTimer(
                fire_at=int(t["fire_at"]),
                expire_at=int(t["expire_at"]),
                target=t["target"],
                message=t["message"],
                priority=int(t["priority"]),
                timer_id=t["id"],
            )
            for t in snap.get("timers", [])
        ]
        self.events = list(snap["events"])
        self.supervision = list(snap["supervision"])
        self.delivered_dedup = list(snap["delivered_dedup"])
        # Restore via the public registration entry point: snapshotted state
        # becomes the new runtime generation's initial state.
        self.rt = ActorRuntime()
        for name in ACTOR_NAMES:
            raw = snap["states"][name]
            if isinstance(raw, dict) and raw.get("stopped"):
                state = initial_state_for(name)
            elif name == A_SUPERVISOR:
                state = {
                    "observed": list(raw["observed"]),
                    "escalations": list(raw["escalations"]),
                }
            else:
                state = {
                    "seen": set(raw["seen"]),
                    "arrivals": list(raw["arrivals"]),
                    "value": raw["value"],
                }
            self.rt.register(name, state, HANDLERS[name])
        # Snapshot restore begins a new generation; its stored trace prefix is
        # observed through result assembly, not this live runtime.
        self.gen_boundaries = list(snap["gen_boundaries"])
        self._stored_trace = [tuple(e) for e in snap["trace"]]
        return len(self._stored_trace)

    # -- execution --------------------------------------------------------

    def run_records(self, records: list[dict], *,
                    rebuild: bool = False) -> ScenarioResult:
        """Apply a complete, ordered record stream.

        ``rebuild`` indicates the stream ends at a supervision boundary and
        enqueuing rules must discard the faulting delivery and deliveries
        whose effects the restart erases; the stream is scanned ahead for
        those positions.
        """
        faulting_positions = self._faulting_positions(records)
        restart_positions = self._restart_positions(records)
        for i, rec in enumerate(records):
            self._step(
                rec, i, records,
                rebuild=rebuild,
                faulting_positions=faulting_positions,
                restart_positions=restart_positions,
            )
        return self._result()

       @staticmethod
    def _faulting_positions(records: list[dict]) -> dict[int, str]:
        """Map record position -> actor when a delivery is immediately
        followed by the supervision record its failure produced."""
        out = {}
        for i in range(len(records) - 1):
            rec, nxt = records[i], records[i + 1]
            if (rec.get("t") == "deliver" and nxt.get("t") == "supervision"
                    and nxt.get("actor") == rec.get("target")):
                out[i] = rec["target"]
        return out

    @staticmethod
    def _restart_positions(records: list[dict]) -> dict[str, int]:
        return {
            rec["actor"]: i
            for i, rec in enumerate(records)
            if rec.get("t") == "supervision" and rec.get("action") == "restart"
        }

    def _later_restart(self, target: str, pos: int,
                       restart_positions: dict[str, int]) -> bool:
        return restart_positions.get(target, -1) > pos

    def _step(self, rec, i, records, *, rebuild, faulting_positions,
              restart_positions) -> None:
        kind = rec["t"]
        if kind == "cap":
            self.cap = rec["n"]
            self.events.append({"at": "cap", "n": rec["n"]})
            return
        if kind == "deliver":
            self._step_deliver(
                rec, i, rebuild, faulting_positions, restart_positions
            )
            return
        if kind == "schedule":
            self._step_schedule(rec)
            return
        if kind == "clock":
            self._step_clock(
                rec, i, rebuild, restart_positions
            )
            return
        if kind == "resolve":
            # First run: the pending fault determines the concrete record.
            assert self.pending_fault is not None, "resolve without fault"
            concrete = self._supervision_record(self.pending_fault)
            records[i] = concrete
            self._step_supervision(concrete)
            self._drain()
            return
        if kind == "supervision":
            self._step_supervision(rec)
            if not rebuild:
                self._drain()
            return
        if kind == "snapshot":
            self._snap_seq = rec["seq"]
            self.snapshots.append((rec["seq"], self.snapshot_blob()))
            self.events.append({"at": "snapshot", "seq": rec["seq"]})
            return
        raise CorruptRecordError(f"unknown record type: {kind!r}")

    def _supervision_record(self, fault: dict) -> dict:
        actor = fault["actor"]
        attempts = self.attempts.get(actor, 0) + 1
        action = self.policy(actor, attempts)
        return {
            "t": "supervision",
            "actor": actor,
            "message_id": fault["message_id"],
            "error_type": fault["error_type"],
            "action": action,
        }

    def _step_deliver(self, rec, i, rebuild, faulting_positions,
                      restart_positions) -> None:
        target = rec["target"]
        message = dict(rec["message"])
        if rec.get("dedup") is not None:
            message["dedup"] = rec["dedup"]
        is_faulting = i in faulting_positions
        discarded_by_restart = (
            rebuild and not is_faulting
            and self._later_restart(target, i, restart_positions)
        )
        accepted = target not in self.stopped and not is_faulting
        if not is_faulting and not discarded_by_restart \
                and target not in self.stopped:
            self.rt.send(target, message, priority=int(rec["priority"]))
        self.events.append({
            "at": "deliver",
            "target": target,
            "kind": message["kind"],
            "priority": int(rec["priority"]),
            "dedup": rec.get("dedup"),
            "redelivery": bool(rec.get("redelivery")),
            "accepted": accepted,
        })
        if rec.get("dedup") is not None:
            self.delivered_dedup.append({
                "dedup": rec["dedup"],
                "duplicate": bool(rec.get("redelivery")),
            })
        if not rebuild:
            self._drain()

    def _step_schedule(self, rec) -> None:
        timer_id = rec["id"]
        message = {"kind": "timer", "token": rec["token"]}
        if rec.get("dedup") is not None:
            message["dedup"] = rec["dedup"]
        self.timers.append(PendingTimer(
            fire_at=self.clock + int(rec["delay"]),
            expire_at=self.clock + int(rec["delay"]) + int(rec["ttl"]),
            target=rec["target"],
            message=message,
            priority=int(rec["priority"]),
            timer_id=timer_id,
        ))
        self.events.append({
            "at": "schedule",
            "id": timer_id,
            "target": rec["target"],
            "fire_at": self.clock + int(rec["delay"]),
        })

    def _step_clock(self, rec, i, rebuild, restart_positions) -> None:
        self.clock += int(rec["ticks"])
        self.events.append({
            "at": "clock",
            "ticks": int(rec["ticks"]),
            "new_clock": self.clock,
        })
        due = [t for t in self.timers if t.fire_at <= self.clock]
        due.sort(key=lambda t: (t.fire_at, t.timer_id))
        self.timers = [t for t in self.timers if t.fire_at > self.clock]
        for timer in due:
            expired = self.clock > timer.expire_at
            erase_by_restart = (
                rebuild
                and self._later_restart(timer.target, i, restart_positions)
            )
            if expired:
                # Expired before it was ever eligible: never enqueued, never
                # reaches a handler.
                self.events.append({
                    "at": "timer_expired",
                    "id": timer.timer_id,
                    "target": timer.target,
                })
                continue
            delivered = (
                timer.target not in self.stopped and not erase_by_restart
            )
            if delivered:
                self.rt.send(
                    timer.target, timer.message, priority=timer.priority
                )
            self.events.append({
                "at": "timer_fired",
                "id": timer.timer_id,
                "target": timer.target,
                "delivered": delivered,
            })
            self.delivered_dedup.append({
                "dedup": timer.timer_id,
                "duplicate": False,
            })
        if not rebuild:
            self._drain()

    def _step_supervision(self, rec) -> None:
        actor = rec["actor"]
        action = rec["action"]
        self.attempts[actor] = self.attempts.get(actor, 0) + 1
        # The fault observation and its supervision decision are both durable
        # facts of the record (nothing can happen between them).
        self.events.append({
            "at": "fault",
            "actor": actor,
            "message_id": rec["message_id"],
            "error_type": rec["error_type"],
        })
        self.events.append({
            "at": "supervision",
            "actor": actor,
            "message_id": rec["message_id"],
            "action": action,
        })
        self.supervision.append({
            "actor": actor,
            "message_id": rec["message_id"],
            "error_type": rec["error_type"],
            "action": action,
        })
        if action in ("stop", "escalate"):
            self.stopped.add(actor)
        if action == "escalate" and actor == A_CHILD:
            self.rt.send(
                A_SUPERVISOR, {"kind": "escalated", "key": actor}
            )

    # -- scheduling -------------------------------------------------------

    def _live_actors_with_mail(self) -> bool:
        return any(
            name not in self.stopped and self.rt.pending_count(name) > 0
            for name in ACTOR_NAMES
        )

    def _drain(self) -> None:
        """Process until idle under the configured in-flight cap.

        Completion order never depends on threads or wall-clock time: each
        step is a public ``run(limit=1)`` and the actor/message selection is
        the runtime's documented registration/priority/id order.  A cap only
        changes batching round size, never that order.
        """
        if self.pending_fault is not None:
            return
        cap = self.cap
        while self._live_actors_with_mail():
            steps = cap if cap is not None else None
            while steps is None or steps > 0:
                if not self._live_actors_with_mail():
                    return
                try:
                    if cap is None:
                        self.rt.run()
                        return
                    self.rt.run(limit=1)
                except ActorExecutionError as exc:
                    self.pending_fault = {
                        "actor": exc.actor_name,
                        "message_id": exc.message_id,
                        "error_type": type(exc.original).__name__,
                    }
                    return
                steps -= 1

    # -- result assembly --------------------------------------------------

    def _states(self) -> dict:
        out = {}
        for name in ACTOR_NAMES:
            if name in self.stopped:
                out[name] = {"stopped": True}
            else:
                out[name] = canonical_state(self.rt.get_state(name))
        return out

    def _live_trace(self) -> list:
        return [
            (
                e.message_id, e.actor_name, e.priority,
                canonical_state(e.state_before),
                canonical_state(e.state_after),
            )
            for e in self.rt.trace()
        ]

    def _result(self, stored_trace: Optional[list] = None,
                stored_boundaries: Optional[list] = None) -> ScenarioResult:
        live = self._live_trace()
        if stored_trace:
            traces = list(stored_trace) + live
            boundaries = list(stored_boundaries or []) + [
                len(stored_trace) + b for b in self.gen_boundaries
            ] + [len(stored_trace)]
        else:
            traces = live
            boundaries = list(self.gen_boundaries)
        return ScenarioResult(
            states=self._states(),
            traces=traces,
            gen_boundaries=sorted(set(boundaries)),
            events=list(self.events),
            supervision=list(self.supervision),
            delivered_dedup=list(self.delivered_dedup),
            snapshots=list(self.snapshots),
        )


# ---------------------------------------------------------------------------
# Facade: first run / replay / recovery
# ---------------------------------------------------------------------------


def execute(script: list, *, cap: Optional[int] = None,
            policy: Callable[[str, int], str] = default_policy
            ) -> ScenarioResult:
    """First execution: normalise, resolve faults, encode journal."""
    records = normalize_script(script)
    interp = Interpreter(cap=cap, policy=policy)
    faulting = Interpreter._faulting_positions
    restart_positions = Interpreter._restart_positions

    i = 0
    while i < len(records):
        rec = records[i]
        if rec.get("t") != "resolve":
            interp.run_records([rec])
            i += 1
            continue
        # A resolve closes the fault produced by the immediately preceding
        # delivery: rebuild from the whole durable prefix, honouring the
        # supervision decision, then continue.
        fault = interp.pending_fault
        assert fault is not None, "resolve without a pending fault"
        concrete = interp._supervision_record(fault)
        records[i] = concrete
        prefix = records[: i + 1]
        rebuilt = Interpreter(cap=cap, policy=policy)
        rebuilt.gen_boundaries.append(0)
        rebuilt.run_records(prefix, rebuild=True)
        rebuilt.pending_fault = None
        interp = rebuilt
        interp._drain()
        i += 1

    journal = encode_records(records)
    result = interp._result()
    result.journal = journal

    # Attach byte offsets of snapshot markers in the final journal.
    offsets = _snapshot_offsets(records, journal)
    snaps = []
    for seq, blob in interp.snapshots:
        snaps.append((seq, offsets[seq], blob))
    result.snapshots = snaps
    return result


def _snapshot_offsets(records: list[dict], journal: bytes) -> dict:
    offsets_of_frames = frame_offsets(journal)
    # offsets_of_frames[0] is the header; record k lives at index k+1.
    out = {}
    for k, rec in enumerate(records):
        if rec.get("t") == "snapshot":
            out[rec["seq"]] = offsets_of_frames[k + 1]
    return out


def replay_journal(journal: bytes, *,
                   cap: Optional[int] = None,
                   policy: Callable[[str, int], str] = default_policy
                   ) -> ScenarioResult:
    """Reconstruct a result from durable bytes alone."""
    records = parse_records(journal)
    interp = Interpreter(cap=cap, policy=policy)
    i = 0
    while i < len(records):
        rec = records[i]
        if rec.get("t") != "supervision":
            interp.run_records([rec])
            i += 1
            continue
        prefix = records[: i + 1]
        rebuilt = Interpreter(cap=cap, policy=policy)
        rebuilt.gen_boundaries.append(0)
        rebuilt.run_records(prefix, rebuild=True)
        rebuilt._drain()
        interp = rebuilt
        i += 1
    result = interp._result()
    result.journal = journal
    return result


def recover_snapshot(snapshot_blob: bytes, journal: bytes, *,
                     marker_offset: int,
                     cap: Optional[int] = None,
                     policy: Callable[[str, int], str] = default_policy
                     ) -> ScenarioResult:
    """Restore from a snapshot blob, then apply the journal suffix."""
    interp = Interpreter(cap=cap, policy=policy)
    stored_len = interp.load_snapshot(snapshot_blob)
    stored_trace = list(interp._stored_trace)
    stored_boundaries = list(interp.gen_boundaries)
    interp.gen_boundaries = [0]  # boundary of the restored generation

    # Suffix: frames strictly after the snapshot marker frame.
    offsets = frame_offsets(journal)
    end_offsets = offsets[1:] + [len(journal)]
    suffix_start = None
    for off, end in zip(offsets, end_offsets):
        if off == marker_offset:
            suffix_start = end
            break
    if suffix_start is None:
        raise CorruptRecordError("snapshot marker not found in journal")
    suffix = parse_records(journal, start_offset=suffix_start) \
        if suffix_start < len(journal) else []

    i = 0
    while i < len(suffix):
        rec = suffix[i]
        if rec.get("t") != "supervision":
            interp.run_records([rec])
            i += 1
            continue
        # A supervision after recovery: rebuild from snapshot + suffix prefix.
        fault = interp.pending_fault
        assert fault is not None
        concrete = interp._supervision_record(fault)
        suffix[i] = concrete
        rebuilt = Interpreter(cap=cap, policy=policy)
        rebuilt.load_snapshot(snapshot_blob)
        rebuilt.events = list(interp.events)
        rebuilt.supervision = list(interp.supervision)
        rebuilt.delivered_dedup = list(interp.delivered_dedup)
        rebuilt.gen_boundaries = [0]
        rebuilt.run_records(suffix[: i + 1], rebuild=True)
        rebuilt.pending_fault = None
        interp = rebuilt
        interp._drain()
        i += 1

    result = interp._result(
        stored_trace=stored_trace,
        stored_boundaries=stored_boundaries,
    )
    result.journal = journal
    return result

