def generate_script(seed: int, *, steps: int = 24) -> list:
    """Fixed finite script mixing sends, clock, faults, snapshot, recovery.

    Layout, chosen to satisfy the replay invariants:
      * a fault window of plain deliveries + fail/resolve pairs;
      * an optional capped scheduling window (no faults);
      * timers + clock advances interleaved with sends and redeliveries;
      * snapshots only after drains, and at least one before the tail.
    """
    rng = DeterministicRng(seed)
    script: list = []
    seq = 0
    dedup_ordinals: list[int] = []

    def add_send(target, *, can_fail=True, want_dedup=None):
        nonlocal seq
        seq += 1
        fault = (
            can_fail
            and target in (A_CHILD, A_COUNTER, A_EVENTS)
            and rng.chance(28)
        )
        if fault:
            key = f"f{seq}"
            script.append(
                ("send", target, {"kind": "fail", "key": key}, 0)
            )
            script.append(("resolve",))
            return None
        message = _message_for(rng, target, seq)
        dedup = want_dedup
        if dedup is None:
            dedup = rng.chance(45)
        prio = rng.choose((-1, 0, 0, 0, 2, 5))
        script.append(("send", target, message, prio, dedup))
        if dedup:
            ordinal = len(dedup_ordinals)
            dedup_ordinals.append(ordinal)
            return ordinal
        return None

    # Phase 1: fault window (plain deliveries only, no cap/timers/then).
    for _ in range(rng.randint(4, 7)):
        target = rng.choose((A_CHILD, A_COUNTER, A_EVENTS, A_SUPERVISOR))
        add_send(target)

    # Phase 2: bounded scheduling window (no faults).
    if rng.chance(70):
        script.append(("cap", rng.choose((1, 2, 3))))
        for _ in range(rng.randint(2, 4)):
            target = rng.choose((A_EVENTS, A_COUNTER))
            seq += 1
            msg = (_message_for(rng, target, seq)
                   if target == A_EVENTS
                   else {"kind": "inc", "n": rng.randint(1, 4)})
            script.append(
                ("send", target, msg, rng.choose((0, 1, 3)),
                 rng.chance(40))
            )
            if script[-1][4]:
                dedup_ordinals.append(len(dedup_ordinals))
        script.append(("cap", None))      # drain before any snapshot

    # Phase 3: timers and clock advances.
    timer_count = rng.randint(1, 3)
    for k in range(timer_count):
        target = rng.choose((A_EVENTS, A_CHILD))
        delay = rng.randint(1, 6)
        # Sometimes ttl is so tight the timer is already stale at firing.
        ttl = rng.choose((0, 0, 100, 100))
        script.append(("schedule", target, f"tm{k}", delay, ttl,
                       rng.choose((0, 2)), rng.chance(70)))
    total_ticks = 0
    for _ in range(rng.randint(2, 4)):
        total_ticks += rng.randint(1, 4)
        script.append(("clock", rng.randint(1, 4)))
        if rng.chance(60):
            target = rng.choose(TARGETS)
            ordinal = add_send(target, can_fail=False)
            if ordinal is not None:
                dedup_ordinals.append(ordinal)

    # Phase 4: redeliveries of an earlier dedup message (at-least-once).
    if dedup_ordinals and rng.chance(75):
        ordinal = rng.choose(dedup_ordinals)
        script.append(("redeliver", ordinal))

    # Mid-stream snapshot (mailboxes are drained: cap is None here).
    script.append(("snapshot",))

    # Phase 5: tail after the snapshot (sends, timers, another snapshot).
    for _ in range(rng.randint(2, 5)):
        target = rng.choose(TARGETS)
        ordinal = add_send(target, can_fail=False)
        if ordinal is not None:
            dedup_ordinals.append(ordinal)
        if dedup_ordinals and rng.chance(30):
            script.append(("redeliver", rng.choose(dedup_ordinals)))
    if rng.chance(60):
        script.append(("schedule", A_EVENTS, "tail-timer", 2, 100, 0, True))
        script.append(("clock", 3))
    script.append(("snapshot",))

    # Pad/trim to the requested finite length bound deterministically.
    return script[:steps] if len(script) > steps else script

